// Enregistre la vidéo reçue en attente de validation (mémoire du workflow).
const data = $getWorkflowStaticData('global');
data.pending = data.pending || {};

const body = $json.body || {};
if (!body.video_url) {
  throw new Error('video_url manquant dans la requête');
}
const id = String(body.id || Date.now().toString(36));
data.pending[id] = { ...body, id, receivedAt: new Date().toISOString() };

return [{ json: { ...body, id } }];

// Prépare le message texte (légendes + brouillons pour les groupes Facebook).
const v = $('Enregistrer en attente').first().json;
const groups = (v.group_posts || [])
  .map((g, i) => `👥 Groupe ${i + 1} – ${g.group || ''}\n${g.text || ''}`)
  .join('\n\n');

const text = [
  `🎬 ${v.id} | promesse : ${v.promesse || '?'} | angle : ${v.angle || '?'} | ton : ${v.ton || '?'} | format : ${v.format || '?'}`,
  '',
  '📘 Facebook :', v.caption_facebook || '-',
  '',
  '🎵 TikTok :', v.caption_tiktok || '-',
  '',
  '▶️ YouTube :', `${v.title_youtube || '-'}\n${v.description_youtube || ''}`,
  '',
  groups ? '— Brouillons groupes FB (à poster toi-même) —\n\n' + groups : '',
].join('\n');

// Telegram limite un message à 4096 caractères : on découpe si besoin.
const chunks = [];
for (let i = 0; i < text.length; i += 4000) chunks.push(text.slice(i, i + 4000));
return chunks.map((t) => ({ json: { text: t } }));

// Lit le clic sur un bouton Telegram (approve:ID / reject:ID).
const ALLOWED_CHAT_ID = 'REMPLACER_PAR_TON_CHAT_ID_TELEGRAM';
const cq = $json.callback_query;
if (!cq || String(cq.from.id) !== ALLOWED_CHAT_ID) {
  return []; // clic d'une autre personne : ignoré
}

const [action, id] = String(cq.data || '').split(':');
const data = $getWorkflowStaticData('global');
data.pending = data.pending || {};
data.history = data.history || [];

const item = data.pending[id];
if (!item) {
  return [{ json: { action: 'unknown', id, callbackId: cq.id } }];
}
delete data.pending[id];

// Historique utilisé par Claude pour apprendre de tes choix.
data.history.push({
  id,
  action,
  date: new Date().toISOString(),
  promesse: item.promesse,
  angle: item.angle,
  ton: item.ton,
  format: item.format,
  hook: item.hook,
});
data.history = data.history.slice(-60);

return [{ json: { ...item, action, id, callbackId: cq.id } }];

// Une requête Buffer par réseau. Remplace les IDs de canaux Buffer.
const CHANNELS = {
  facebook: 'REMPLACER_ID_CANAL_FACEBOOK',
  tiktok: 'REMPLACER_ID_CANAL_TIKTOK',
  youtube: 'REMPLACER_ID_CANAL_YOUTUBE',
};

const MUTATION = `mutation CreatePost($input: CreatePostInput!) {
  createPost(input: $input) {
    ... on PostActionSuccess { post { id } }
    ... on MutationError { message }
  }
}`;

const v = $('Lire la décision').first().json;
const texts = {
  facebook: v.caption_facebook,
  tiktok: v.caption_tiktok,
  youtube: `${v.title_youtube || ''}\n\n${v.description_youtube || ''}`.trim(),
};

return Object.entries(CHANNELS)
  .filter(([, channelId]) => channelId && !channelId.startsWith('REMPLACER'))
  .map(([network, channelId]) => ({
    json: {
      network,
      body: {
        query: MUTATION,
        variables: {
          input: {
            text: texts[network] || v.caption_facebook || '',
            channelId,
            schedulingType: 'automatic',
            mode: 'addToQueue',
            assets: [{ video: { url: v.video_url } }],
          },
        },
      },
    },
  }));

// Résume ce que Buffer a accepté ou refusé.
const lines = $input.all().map((it, i) => {
  const network = $('Préparer posts Buffer').all()[i]?.json.network || '?';
  const r = it.json?.data?.createPost;
  const err = it.json?.errors?.[0]?.message || r?.message;
  return err ? `❌ ${network} : ${err}` : `✅ ${network} : programmé (post ${r?.post?.id || '?'})`;
});
const id = $('Lire la décision').first().json.id;
return [{ json: { text: `Vidéo ${id}\n` + (lines.join('\n') || 'Aucun canal configuré.') } }];

// Renvoie l'historique des décisions à Claude.
const data = $getWorkflowStaticData('global');
return [{
  json: {
    history: data.history || [],
    pending: Object.keys(data.pending || {}),
  },
}];
